import numpy as np
import pandas as pd
from typing import Any


class AmesHousingMetrics:
    """Metric class for Ames Housing Price Prediction using RMSLE."""

    def __init__(self, value: str = "SalePrice", higher_is_better: bool = False):
        self.higher_is_better = higher_is_better
        self.value = value

    def evaluate(self, y_true: pd.DataFrame = None, y_pred: pd.DataFrame = None) -> float:
        """Calculate RMSE between log of predicted and log of actual SalePrice."""
        # Merge on Id to ensure alignment
        merged = pd.merge(y_true, y_pred, on="Id", suffixes=("_true", "_pred"))

        true_values = merged[f"{self.value}_true"].values.astype(float)
        pred_values = merged[f"{self.value}_pred"].values.astype(float)

        # Clip to avoid log(0) or log(negative)
        true_values = np.clip(true_values, 1e-15, None)
        pred_values = np.clip(pred_values, 1e-15, None)

        log_true = np.log(true_values)
        log_pred = np.log(pred_values)

        rmse = np.sqrt(np.mean((log_pred - log_true) ** 2))

        return float(rmse)

    def validate_submission(self, submission: Any, ground_truth: Any) -> str:
        if not isinstance(submission, pd.DataFrame):
            raise Exception("Submission must be a pandas DataFrame. Please provide a valid pandas DataFrame.")
        if not isinstance(ground_truth, pd.DataFrame):
            raise Exception("Ground truth must be a pandas DataFrame. Please provide a valid pandas DataFrame.")

        if "Id" not in submission.columns:
            raise Exception("Submission must contain an 'Id' column.")
        if "Id" not in ground_truth.columns:
            raise Exception("Ground truth must contain an 'Id' column.")

        if self.value not in submission.columns:
            raise Exception(f"Submission must contain the '{self.value}' column.")
        if self.value not in ground_truth.columns:
            raise Exception(f"Ground truth must contain the '{self.value}' column.")

        if len(submission) != len(ground_truth):
            raise Exception(
                f"Number of rows in submission ({len(submission)}) does not match "
                f"ground truth ({len(ground_truth)}). Please ensure both have the same number of rows."
            )

        # Check that all Ids in ground truth are present in submission
        gt_ids = set(ground_truth["Id"].values)
        sub_ids = set(submission["Id"].values)
        if gt_ids != sub_ids:
            raise Exception("The set of Ids in submission does not match the set of Ids in ground truth.")

        # Check for NaN values in submission SalePrice
        if submission[self.value].isnull().any():
            raise Exception(f"Submission contains NaN values in the '{self.value}' column.")

        # Check for non-positive values
        if (submission[self.value] <= 0).any():
            raise Exception(f"Submission contains non-positive values in the '{self.value}' column. All prices must be positive.")

        return "Submission is valid."

from typing import Any
import pandas as pd


class SpaceshipTitanicMetrics:
    """Metric class for Spaceship Titanic competition using Classification Accuracy."""

    def __init__(self, value: str = "Transported", higher_is_better: bool = True):
        self.higher_is_better = higher_is_better
        self.value = value

    def _parse_bool(self, series: pd.Series) -> pd.Series:
        """Convert string or boolean values to consistent boolean."""
        def convert(val):
            if isinstance(val, bool):
                return val
            if isinstance(val, str):
                return val.strip().lower() == "true"
            # Handle numpy bool etc.
            return bool(val)
        return series.apply(convert)

    def evaluate(self, y_true: pd.DataFrame = None, y_pred: pd.DataFrame = None) -> float:
        """Calculate classification accuracy between predictions and true labels."""
        if self.value not in y_true.columns or self.value not in y_pred.columns:
            raise Exception(f"Both ground truth and submission must contain the '{self.value}' column.")

        # Align by PassengerId if present
        if "PassengerId" in y_true.columns and "PassengerId" in y_pred.columns:
            merged = y_true[["PassengerId", self.value]].merge(
                y_pred[["PassengerId", self.value]],
                on="PassengerId",
                suffixes=("_true", "_pred")
            )
            true_vals = self._parse_bool(merged[f"{self.value}_true"])
            pred_vals = self._parse_bool(merged[f"{self.value}_pred"])
        else:
            true_vals = self._parse_bool(y_true[self.value].reset_index(drop=True))
            pred_vals = self._parse_bool(y_pred[self.value].reset_index(drop=True))

        if len(true_vals) == 0:
            raise Exception("No matching records found for evaluation.")

        accuracy = (true_vals == pred_vals).mean()
        return float(accuracy)

    def validate_submission(self, submission: Any, ground_truth: Any) -> str:
        if not isinstance(submission, pd.DataFrame):
            raise Exception("Submission must be a pandas DataFrame. Please provide a valid pandas DataFrame.")
        if not isinstance(ground_truth, pd.DataFrame):
            raise Exception("Ground truth must be a pandas DataFrame. Please provide a valid pandas DataFrame.")

        if len(submission) != len(ground_truth):
            raise Exception(
                f"Number of rows in submission ({len(submission)}) does not match "
                f"ground truth ({len(ground_truth)}). Please ensure both have the same number of rows."
            )

        if self.value not in submission.columns:
            raise Exception(f"Submission must contain the '{self.value}' column.")
        if self.value not in ground_truth.columns:
            raise Exception(f"Ground truth must contain the '{self.value}' column.")

        if "PassengerId" in ground_truth.columns and "PassengerId" not in submission.columns:
            raise Exception("Submission must contain the 'PassengerId' column.")

        if "PassengerId" in ground_truth.columns and "PassengerId" in submission.columns:
            gt_ids = set(ground_truth["PassengerId"])
            sub_ids = set(submission["PassengerId"])
            if gt_ids != sub_ids:
                raise Exception("PassengerId values in submission do not match those in ground truth.")

        # Check for null values in the target column
        if submission[self.value].isnull().any():
            raise Exception(f"Submission contains null values in the '{self.value}' column.")

        return "Submission is valid."

from typing import Any
import pandas as pd
import numpy as np


class TitanicMetrics:
    """Metric class for Titanic - Machine Learning from Disaster competition using Accuracy."""

    def __init__(self, value: str = "Survived", higher_is_better: bool = True):
        self.higher_is_better = higher_is_better
        self.value = value
        self.id_column = "PassengerId"

    def evaluate(self, y_true: pd.DataFrame = None, y_pred: pd.DataFrame = None) -> float:
        """Calculate accuracy between the predictions and the true labels."""
        # Merge on PassengerId to ensure correct alignment
        merged = pd.merge(
            y_true[[self.id_column, self.value]],
            y_pred[[self.id_column, self.value]],
            on=self.id_column,
            suffixes=("_true", "_pred"),
        )

        if len(merged) == 0:
            raise Exception("No matching PassengerIds found between submission and ground truth.")

        true_vals = merged[f"{self.value}_true"].astype(int)
        pred_vals = merged[f"{self.value}_pred"].astype(int)

        accuracy = (true_vals == pred_vals).mean()
        return float(accuracy)

    def validate_submission(self, submission: Any, ground_truth: Any) -> str:
        if not isinstance(submission, pd.DataFrame):
            raise Exception("Submission must be a pandas DataFrame.")
        if not isinstance(ground_truth, pd.DataFrame):
            raise Exception("Ground truth must be a pandas DataFrame.")

        # Check required columns
        if self.id_column not in submission.columns:
            raise Exception(f"Submission must contain the '{self.id_column}' column.")
        if self.value not in submission.columns:
            raise Exception(f"Submission must contain the '{self.value}' column.")
        if self.id_column not in ground_truth.columns:
            raise Exception(f"Ground truth must contain the '{self.id_column}' column.")
        if self.value not in ground_truth.columns:
            raise Exception(f"Ground truth must contain the '{self.value}' column.")

        # Check number of rows
        if len(submission) != len(ground_truth):
            raise Exception(
                f"Number of rows in submission ({len(submission)}) does not match "
                f"ground truth ({len(ground_truth)})."
            )

        # Check that all PassengerIds in ground truth are present in submission
        gt_ids = set(ground_truth[self.id_column])
        sub_ids = set(submission[self.id_column])
        if gt_ids != sub_ids:
            missing = gt_ids - sub_ids
            extra = sub_ids - gt_ids
            msg = "PassengerId mismatch."
            if missing:
                msg += f" Missing IDs: {sorted(missing)[:10]}..."
            if extra:
                msg += f" Extra IDs: {sorted(extra)[:10]}..."
            raise Exception(msg)

        # Check that Survived values are binary (0 or 1)
        unique_vals = submission[self.value].dropna().unique()
        for v in unique_vals:
            if int(v) not in (0, 1):
                raise Exception(
                    f"Survived column must contain only 0 or 1 values. Found: {v}"
                )

        # Check for NaN in Survived
        if submission[self.value].isna().any():
            raise Exception("Submission contains NaN values in the Survived column.")

        return "Submission is valid."
